-- [x] RuntimeHelper; original byte offset 907538
x=function(_vm, o, N, B, Z, x, I, i, C, f)
	if B <= 125 then
		local e, K, U, s = _vm[31](C, 3 + x), o - 128, 2097152 * (I - 128), 16384 * (N - 128)
		local I, u, t = 128 * (e % 128) + (s + (e - e % 128) * 2097152) + (U + K), 4 + x, f[1]
		return 64, f[2], t, I, u, N
	elseif B <= 126 then
		local B, I = N - 128, 128 * (Z - 128)
		local e, K, U = 16384 * i + (B + I), 3 + x, f[1]
		return 271, f[2], U, o, K, e
	else
		local B, I = _vm[31](C, 3 + x), N - 128
		local L, N, C =
			2097152 * (Z - 128) + ((i - 128) * 16384 + (128 * (B % 128) + 2097152 * (B - B % 128)) + I), 4 + x, f[1]
		return 256, f[2], C, o, N, L
	end
end,

